def test_iterates_only_unread():
    messages = [{'text': 'hi', 'read': True}, {'text': 'call me', 'read': False}, {'text': 'urgent', 'read': False}]
    result = list(UnreadMessages(messages))
    assert result == [messages[1], messages[2]], 'must yield only messages with read=False, in order'

def test_iter_returns_self():
    it = UnreadMessages([])
    assert iter(it) is it, '__iter__ must return self so the object is its own iterator'

def test_raises_stop_iteration_when_exhausted():
    it = UnreadMessages([{'text': 'a', 'read': False}])
    next(it)
    try:
        next(it)
        assert False, 'calling next() past the last unread message must raise StopIteration'
    except StopIteration:
        pass

