class UnreadMessages:
    def __init__(self, messages):
        self.messages = messages
        self.index = 0

    def __iter__(self):
        return self

    def __next__(self):
        while self.index < len(self.messages):
            message = self.messages[self.index]
            self.index += 1
            if not message['read']:
                return message
        raise StopIteration
